package com.xvso.game;
import android.app.Activity;import android.os.Bundle;import android.view.View;import android.webkit.WebView;import android.webkit.WebViewClient;
public class MainActivity extends Activity { @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);WebView w=new WebView(this);w.setBackgroundColor(0xff02091e);w.setWebViewClient(new WebViewClient());w.getSettings().setJavaScriptEnabled(true);w.getSettings().setDomStorageEnabled(true);setContentView(w);w.loadUrl("file:///android_asset/index.html");}}